using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
class TaskbarLayoutTests {
 static int checks,failures;static void Check(string name,bool ok){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(!ok)failures++;}
 static int TextWidth(Graphics g,string text,Font f){return TextRenderer.MeasureText(g,text,f,new Size(Int32.MaxValue,Int32.MaxValue),TextFormatFlags.NoPadding|TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix).Width;}
 [STAThread]static int Main(string[] args){try{var c=new MonitorConfig();c.Appearance.AutoWidth=true;c.Appearance.ValueWidth=240;int wide=TaskbarPainter.Geometry(c,1,48).Size.Width;c.Appearance.ValueWidth=35;int narrow=TaskbarPainter.Geometry(c,1,48).Size.Width;Check("automatic text sizing ignores manual-only width",wide==narrow);int withUnits=narrow;c.Appearance.HideUnits=true;int withoutUnits=TaskbarPainter.Geometry(c,1,48).Size.Width;Check("actual unit format controls automatic width",withoutUnits<withUnits);
 var sample=new SystemSample{Cpu=61,MemoryUsed=8,MemoryTotal=16,Gpu=40,CpuTemperature=47,GpuTemperature=41,DiskBusy=12,Download=123.45*1048576,Upload=128*1024};c.TaskbarItems=TaskbarAppearance.Keys.ToList();c.Appearance.FontName="Microsoft YaHei UI";c.Appearance.HideUnits=false;c.Appearance.UnitSpace=false;foreach(double dpi in new[]{1.0,1.25,1.5,2.0}){var layout=TaskbarPainter.Geometry(c,dpi,(int)(48*dpi),sample);using(var b=new Bitmap(1,1))using(var g=Graphics.FromImage(b))using(var font=TaskbarPainter.Font(c.Appearance,layout.RenderDpi)){bool fits=true;for(int i=0;i<c.TaskbarItems.Count;i++){string key=c.TaskbarItems[i];fits&=layout.Values[i].Width>=TextWidth(g,TaskbarPainter.Format(sample,key,c.Appearance),font);fits&=layout.Labels[i].Width>=TextWidth(g,c.Appearance.Item(key).Label,font);fits&=layout.Cells[i].Right<=layout.Size.Width+.01&&layout.Cells[i].Bottom<=layout.Size.Height+.01;}Check("GDI text fits all labels/values at DPI "+dpi,fits);}}
 c.TaskbarItems=new List<string>{"cpu","memory","gpu"};var odd=TaskbarPainter.Geometry(c,1,48,sample);Check("unpaired item uses full-height stacked label/value",odd.Stacked[2]&&odd.Cells[2].Height>odd.Cells[0].Height&&odd.Values[2].Top>odd.Labels[2].Top);c.TaskbarItems=new List<string>{"cpu","memory"};c.Appearance.PaddingLeft=19;c.Appearance.PaddingRight=27;c.Appearance.PaddingTop=3;c.Appearance.PaddingBottom=7;var asym=TaskbarPainter.Geometry(c,1,100,sample);Check("asymmetric left/right padding preserved",asym.Cells[0].Left==19&&Math.Abs(asym.Size.Width-asym.Cells[0].Right-27)<1);Check("asymmetric top/bottom padding preserved",asym.Cells[0].Top==3&&Math.Abs(asym.Size.Height-asym.Cells[1].Bottom-7)<1);c.Appearance.AutoRows=false;c.Appearance.FontSize=24;Check("manual row count is respected",TaskbarPainter.Geometry(c,1,30,sample).Rows==2);c.Appearance.AutoRows=true;Check("automatic row fitting responds to height",TaskbarPainter.Geometry(c,1,30,sample).Rows==1);
 c=new MonitorConfig{Appearance=new TaskbarAppearance{FontSize=14,AutoFit=true,FitWidth=260,FitHeight=40},TaskbarItems=new List<string>{"cpu","memory","gpu","disk","download","upload"}};var fitted=TaskbarPainter.Geometry(c,1,48,sample,300);Check("adaptive layout reduces scale into selected bounds",fitted.RenderDpi<1&&fitted.Size.Width<=260&&fitted.Size.Height<=40);Check("adaptive font remains at least seven points",c.Appearance.FontSize*fitted.RenderDpi>=7);Check("auto fitting does not overwrite user font and margins",c.Appearance.FontSize==14&&c.Appearance.Padding==6);
 c=new MonitorConfig{Appearance=TaskbarAppearance.Preset("紧凑双行"),TaskbarItems=new List<string>{"cpu","memory"}};c.Appearance.Graphs=false;c.Appearance.Transparent=true;c.Appearance.AutoTheme=false;c.Appearance.LabelColor=c.Appearance.ValueColor="#FFFFFF";using(var b=TaskbarPainter.Preview(c,sample)){int opaque=0,transparent=0;for(int x=0;x<b.Width;x++)for(int y=0;y<b.Height;y++){if(b.GetPixel(x,y).A==0)transparent++;else opaque++;}Check("GDI preview keeps both visible text and transparent pixels",opaque>30&&transparent>30);}
 }catch(Exception e){Console.WriteLine(e);failures++;}Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],"layout-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");Console.WriteLine("Checks "+checks+" Failures "+failures);return failures==0?0:1;}
}
